using Microsoft.EntityFrameworkCore;

public class OnboardingContext : DbContext
{
    public OnboardingContext(DbContextOptions<OnboardingContext> options)
        : base(options)
    {
    }

    public DbSet<OnboardingEntity> OnboardingEntities { get; set; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<OnboardingEntity>(entity =>
        {
            // Table name
            entity.ToTable("OnboardingRecords");

            // Primary Key
            entity.HasKey(e => e.Id)
                .HasName("PK_Onboarding");

            // Columns
            entity.Property(e => e.Id)
                .HasColumnName("id")
                .ValueGeneratedOnAdd();

            entity.Property(e => e.DeviceGUID)
                .HasColumnName("device_guid")
                .IsRequired()
                .HasMaxLength(36); // Matching GUID format

            entity.Property(e => e.InvitationCode)
                .HasColumnName("invitation_code")
                .IsRequired()
                .HasMaxLength(36);

            entity.Property(e => e.APIKey1)
                .HasColumnName("api_key_1")
                .IsRequired()
                .HasMaxLength(36);

            entity.Property(e => e.APIKey2)
                .HasColumnName("api_key_2")
                .IsRequired()
                .HasMaxLength(36);

            entity.Property(e => e.LastConnectionDateTime)
                .HasColumnName("last_connection_datetime")
                .IsRequired()
                .HasMaxLength(50); // Allowing space for ISO 8601 format

            entity.Property(e => e.LastConnectionIP)
                .HasColumnName("last_connection_ip")
                .IsRequired()
                .HasMaxLength(50);

            entity.Property(e => e.LastConnectionUserID)
                .HasColumnName("last_connection_user_id")
                .IsRequired()
                .HasMaxLength(50);

            // Encryption
            entity.Property(e => e.InvitationCode).HasAnnotation("EncryptColumn", true);
            entity.Property(e => e.APIKey1).HasAnnotation("EncryptColumn", true);
            entity.Property(e => e.APIKey2).HasAnnotation("EncryptColumn", true);
        });
    }
}
